<?php require __DIR__.'/../../bootstrap/app.php';role_required('admin');$db=Database::get();
function rate_ok($v):bool{return is_numeric($v)&&$v>=0&&$v<=100;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';$rate=trim((string)($_POST['rate']??''));
 if($a==='remove'){$db->prepare("UPDATE commission_settings SET is_active=0 WHERE id=? AND scope_type<>'default'")->execute([(int)($_POST['id']??0)]);audit('remove commission override','commission');notice('Override removed.');go('admin/commission.php');}
 if(!rate_ok($rate)){notice('Enter a rate between 0 and 100.');go('admin/commission.php');}
 $t=$a==='default'?'default':(in_array($_POST['scope_type']??'',['category','technician'],true)?$_POST['scope_type']:'');$sid=$t==='default'?null:(int)($_POST['scope_id']??0);
 if($t===''||($t!=='default'&&!$sid)){notice('Choose who the override applies to.');go('admin/commission.php');}
 $e=$db->prepare("SELECT id FROM commission_settings WHERE scope_type=? AND (scope_id<=>?) AND is_active=1 LIMIT 1");$e->execute([$t,$sid]);$id=$e->fetchColumn();
 if($id)$db->prepare("UPDATE commission_settings SET rate_percent=? WHERE id=?")->execute([$rate,$id]);else $db->prepare("INSERT INTO commission_settings(scope_type,scope_id,rate_percent) VALUES(?,?,?)")->execute([$t,$sid,$rate]);
 audit('set commission '.$t,'commission',(int)$id,['rate'=>$rate,'scope'=>$sid]);notice('Commission rate saved. It applies to payments recorded from now on.');go('admin/commission.php');}
$def=$db->query("SELECT rate_percent FROM commission_settings WHERE scope_type='default' AND is_active=1 ORDER BY id DESC LIMIT 1")->fetchColumn();
$ov=$db->query("SELECT cs.id,cs.scope_type,cs.rate_percent,COALESCE(c.name,u.name) who FROM commission_settings cs LEFT JOIN service_categories c ON cs.scope_type='category' AND c.id=cs.scope_id LEFT JOIN users u ON cs.scope_type='technician' AND u.id=cs.scope_id WHERE cs.is_active=1 AND cs.scope_type<>'default' ORDER BY cs.id DESC")->fetchAll();
$cats=$db->query("SELECT id,name FROM service_categories ORDER BY name")->fetchAll();$techs=$db->query("SELECT u.id,u.name FROM users u JOIN roles r ON r.id=u.role_id WHERE r.name='technical' ORDER BY u.name")->fetchAll();
$title='Commission';require __DIR__.'/../../app/Views/header.php';?><section class="section"><div class="container"><div class="dash"><?php require __DIR__.'/../../app/Views/admin_nav.php';?><div><h1>Commission settings</h1><p>The company keeps this percentage of each payment. The technician receives the rest. Priority: technician override, then service category, then default.</p>
<form method="post" class="cardx mb-4 d-flex gap-2 align-items-end"><?=csrf_field()?><input type="hidden" name="action" value="default"><div><label>Default rate (%)</label><input class="form-control" name="rate" required value="<?=e($def===false?'':(string)$def)?>"></div><button class="btn btn-dark">Save default</button><?php if($def===false):?><span class="text-danger">Not set yet: payments cannot be recorded until you set it.</span><?php endif;?></form>
<?php foreach([['technician','Technician',$techs],['category','Service category',$cats]] as [$st,$lab,$list]):?><form method="post" class="cardx mb-3 row g-2"><?=csrf_field()?><input type="hidden" name="action" value="override"><input type="hidden" name="scope_type" value="<?=e($st)?>"><div class="col-md-5"><label><?=e($lab)?> override</label><select class="form-select" name="scope_id"><?php foreach($list as $x):?><option value="<?=(int)$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label>Rate %</label><input class="form-control" name="rate" required></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-dark w-100">Save</button></div></form><?php endforeach;?>
<table class="table"><tr><th>Type</th><th>Applies to</th><th>Rate</th><th></th></tr><?php foreach($ov as $r):?><tr><td><?=e($r['scope_type'])?></td><td><?=e($r['who'])?></td><td><?=e($r['rate_percent'])?>%</td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="remove"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-link text-danger p-0">Remove</button></form></td></tr><?php endforeach;?><?php if(!$ov):?><tr><td colspan="4">No overrides.</td></tr><?php endif;?></table></div></div></div></section><?php require __DIR__.'/../../app/Views/footer.php';?>